CREATE TABLE social_oauth_accounts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, platform text NOT NULL, external_id text NOT NULL, name text NOT NULL, token_ref text NOT NULL, status text NOT NULL, health jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_posts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, content jsonb NOT NULL, media jsonb NOT NULL DEFAULT '[]', account_ids jsonb NOT NULL, schedule_at timestamptz, status text NOT NULL, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_post_deliveries (id uuid PRIMARY KEY, post_id uuid NOT NULL, account_id uuid NOT NULL, platform text NOT NULL, status text NOT NULL, attempt int NOT NULL DEFAULT 0, external_post_id text, error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_inbox_messages (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, account_id uuid NOT NULL, platform text NOT NULL, message_type text NOT NULL, sender jsonb NOT NULL, body text NOT NULL, media jsonb NOT NULL DEFAULT '[]', received_at timestamptz NOT NULL);
CREATE TABLE social_replies (id uuid PRIMARY KEY, message_id text NOT NULL, tenant_id uuid NOT NULL, body text NOT NULL, media jsonb NOT NULL DEFAULT '[]', provider_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_assets (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, asset_type text NOT NULL, name text NOT NULL, url text, prompt text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
